# Añade esto después de todas las listas DATOS_SUSTANCIAS.

SUSTANCIAS = []
_SUSTANCIAS_VISTAS = set()

for formula, nombre, descripcion1, descripcion2 in DATOS_SUSTANCIAS:
    clave = (formula, nombre.casefold())

    # Evita entradas repetidas si se copian todos los bloques del catálogo.
    if clave in _SUSTANCIAS_VISTAS:
        continue

    _SUSTANCIAS_VISTAS.add(clave)

    SUSTANCIAS.append({
        "formula": formula,
        "nombre": nombre,
        "descripcion1": descripcion1.strip(),
        "descripcion2": descripcion2.strip(),
    })
